{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    total_capacity = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > total_capacity:
        raise ValueError('Invalid budget')
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                next_pos = allocations[i] + 1
                priority = s['importance'] / next_pos
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"
}
